return {
    ["\"交易从不免费，但契约保证它不会食言。\""] = "«Транзакции никогда не бывают бесплатными, но контракт гарантирует, что компания не нарушит своего слова».",
    ["<Highlight>仅限猎杀时刻活动期间</>于【命运祭坛】处召唤命运人偶，将其击败可获得猩红遗物材料。王城区域危机四伏，建议<Highlight>团队前往挑战</>。"] = "<Highlight> Только во время события </> «Время охоты» вы можете вызвать Марионетку Судьбы на [Алтаре Судьбы]. Победа над ним даст материалы Алой реликвии. Район Королевского города таит в себе опасность; команде <Highlight> рекомендуется бросить вызов </>.",
    ["<Highlight>叹息之种·争怪任务可接取次数</>，任务目标为<Highlight>前往指定争怪区域接取并击败试炼怪物</>。"] = "<Highlight> Оставшиеся попытки выполнения квеста «Семя вздохов: Спор монстров» </>. Цель квеста состоит в том, чтобы <Highlight> отправился в назначенную зону спора, чтобы принять и победить испытательного монстра </>.",
    ["<Highlight>叹息之种·狩怪任务可接取次数</>，任务目标为<Highlight>寻找并击败猎龙之城中游荡的骑士</>。"] = "<Highlight> Оставшиеся попытки выполнения квеста «Семя вздохов: Охота на монстров» </>. Цель квеста — <Highlight> найти и победить рыцарей, блуждающих в Городе охоты на драконов </>.",
    ["<Highlight>工艺：</>亚麻精纺·书页压纹·敞襟长袍\n心怀敬畏，窥探神秘，直至此身明晰万物之真理，方能止息。"] = "<Highlight>Ремесло:</> Тонкопряденый лен · Тиснение в виде книжных страниц · Распашная мантия\nХрани в сердце благоговение, взирай на тайны и не ведай покоя, пока тело сие не постигнет истину всего сущего.",
    ["<Highlight>工艺：</>压纹皮革·银铆轻铠·轻便战甲\n永不流动的黄昏停滞于肩甲，哪怕此身沐浴落日，仍有唤醒黎明之志。"] = "<Highlight> Мастерство: </> Тисненая кожа · Легкая броня с серебряными заклепками · Легкая броня \n Непрекращающиеся сумерки застаиваются на наплечных доспехах. Даже если тело купается в лучах заходящего солнца, оно все равно желает проснуться на рассвете.",
    ["<Highlight>工艺：</>圣者之布·日光镶边·垂坠圣甲\n至诚至纯的灵魂，将如日光般神圣，赤心颂唱时，太阳也为你首肯。"] = "<Highlight>Мастерство: </>Ткань святого · Солнечная кайма · Ниспадающие священные латы\nДуша, исполненная искренней чистоты, священна, точно солнечный свет. Когда вы воспеваете хвалу от чистого сердца, само Солнце склоняет главу в знак согласия.",
    ["<Highlight>工艺：</>星尘细呢·旅迹纹样·短斗篷套装\n星空浩瀚，凡门皆达。披戴此身，愿旅途的星辉指引你们永不迷失。"] = "<Highlight>Мастерство: </>Тонкое сукно «Звёздная пыль» · Узоры странствий · Комплект с короткой накидкой\nЗвёздное небо необъятно, и все врата достижимы. Облачитесь в эти одеяния, и пусть звёздный свет странствия ведёт вас так, чтобы вы никогда не сбились с пути.",
    ["<Highlight>工艺：</>雾灰精纺·暗纹提花·占卜之服\n即便在命运的巨变到来之际，也别忘记嘴角上扬，嘲弄于它。"] = "<Highlight>Мастерство: </>Туманно-серая шерсть · Жаккард с теневым узором · Одеяние прорицателя\nДаже когда судьба обрушивает великие потрясения, не забывайте улыбнуться и посмеяться ей в лицо.",
    ["<Highlight>工艺：</>驼绒精呢·修身剪裁·剧场礼服\n观众总是置身幕后，静观一切戏剧之欢呼，洞悉一切角色之走向。"] = "<Highlight>Отделка: </>Верблюжье сукно · Приталенный крой · Театральный наряд\nЗритель всегда остается за кулисами, наблюдая за рукоплесканиями театральных драм и прозревая судьбы всех действующих лиц.",
    ["<Highlight>接取叹息之种任务后</>，猩红遗物可通过击杀<Highlight>猎龙之城中的超凡生物</>或击败其他敌对玩家<Highlight>掠夺获取</>。当被敌方玩家击杀时，<Highlight>猩红遗物也将按比例掉落</>。\n可将其提交至<Highlight>【猎杀管家】</>处推进<Highlight>猎杀进度</>奖励。<Highlight>猩红遗物仅在猎龙之城内有效</>，离开后将<Highlight>自动失效并清除</>。"] = "<Highlight>После принятия задания «Семя вздохов»</> алые реликвии можно получить за уничтожение <Highlight>потусторонних существ в Городе драконьей охоты</> или отобрать силой, <Highlight>побеждая враждебных игроков</>. При гибели от руки вражеского игрока <Highlight>алые реликвии также выпадают в определённой пропорции</>.\nИх можно сдать <Highlight>【Распорядителю охоты】</>, чтобы продвинуться в получении наград за <Highlight>прогресс охоты</>. <Highlight>Алые реликвии действуют только в Городе драконьей охоты</>; при выходе из локации они <Highlight>автоматически сгорают и удаляются</>.",
    ["“2”级封印物提升到“1”级封印物的必要素材。"] = "Necessary material to upgrade a Grade 2 Запечатанный артефакт to a Grade 1 Запечатанный артефакт.",
    ["“3”级封印物提升到“2”级封印物的必要素材。"] = "Материал, необходимый для улучшения Запечатанного Артефакта 3-го Уровня до Запечатанного Артефакта 2-го Уровня.",
    ["“封印物的历史投影消散时，会留下一段独属于它的历史气息。”\n“这些有什么用处吗？”\n“当然，历史气息可以提升封印物的等级和能力，最高提升到到1级，也就是高度危险状态。”\n“能提升到0级吗？”\n“0级？你们这些天真的小脑瓜真敢想啊，至少升到中序列再考虑这些吧！”"] = "— Когда историческая проекция Запечатанного Артефакта рассеивается, она оставляет частицу своего уникального исторического дыхания.\n— А какая от этого польза?\n— О, историческое дыхание способно повысить уровень и силу Запечатанного Артефакта вплоть до 1-го уровня — то есть до состояния крайней опасности.\n— А до уровня 0 можно поднять?\n— До нулевого?! Ну и наивные же у вас мысли в головах! Дорастите сперва хотя бы до средних Последовательностей, а потом уже заикайтесь о таком!",
    ["“愚者”先生从历史中定位到了无数神话生物，利用“嫁接”将力量转移到源堡，得到了神话织茧。"] = "Мистер «Шут» обнаружил бесчисленное количество мифических существ из истории, использовал «прививку», чтобы передать силу Замку Источника, и получил мифический кокон.",
    ["“正义”女士的馈赠，给人一种莫名的安心感。降低你受到的伤害，并把承受过的苦难化作财富，按累积伤害提升防御。财富压身太久，你会不堪重负。"] = "Подарок от госпожи Джастис, дающий необъяснимое чувство покоя. Он уменьшает получаемый вами урон и превращает перенесенные вами страдания в богатство, увеличивая защиту на основе накопленного урона. Если богатство будет тяготить вас слишком долго, вы будете разбиты.",
    ["一个神奇的无评级封印物，既能辅助战斗，也可以回答问题。当你问它一个问题时，它的触手会轻轻抖动，然后给出答案。虽然是一只乌贼，但它确实知道很多事。\n无评级，无编号，无人知道它究竟是怎么做到的。"] = "Удивительный Запечатанный Артефакт без класса допуска: он способен как помогать в бою, так и отвечать на любые вопросы. Стоит задать ему вопрос, как его щупальца слегка шевельнутся и выдадут ответ. Хоть это и обычный с виду кальмар, он знает поразительно много.\nБез класса, без номера — и никто не ведает, как именно ему это удается.",
    ["一个马桶，干净漂亮，骄傲地伫立在明亮的盥洗室里。"] = "Туалет, чистый и красивый, гордо стоял в светлой умывальной.",
    ["一份泛黄的契约文书，被蓝色亚麻绳捆缚，散发着秩序的力量，不可扭曲，不可摧毁。"] = "Пожелтевший контрактный документ, перевязанный синей льняной веревкой, излучающий силу порядка; его нельзя исказить или уничтожить.",
    ["一命换一命，一纸替一人。"] = "Жизнь за жизнь, бумага за человека.",
    ["一块精心切割的透明棱镜，能够折射光线，也能\"折射\"记忆的容量，让你的表演动作更加丰富多彩。"] = "Тщательно вырезанная прозрачная призма, способная преломлять свет, а также «преломлять» объем памяти, делая ваши движения более насыщенными и красочными.",
    ["一张1苏勒的钞票，色泽墨绿泛白，印着鲁恩国王乔治三世严肃的脸。"] = "Банкнота достоинством в 1 су, зеленовато-белого оттенка, с напечатанным строгим профилем короля Лоэна Георга III.",
    ["一张泛黄的羊皮纸，上面用古赫密斯语写着几行模糊的咒文，隐约能感受到契约那边连接的强大灵性力量。"] = "Пожелтевший кусок пергамента с несколькими строками размытых заклинаний, написанных древним Гермесом, слабо ощущающим мощную духовную силу, связанную с другой стороной контракта.",
    ["一张蕴含庞大灵性的卡牌，持有者可以此媒介沟通灵界，进行运气与命运的交换，从灵界中获取宝物。"] = "Карта, содержащая огромную Духовность; владелец может использовать её как медиум для связи с Миром Духов, обмена удачей и судьбой, а также получения сокровищ из Мира Духов.",
    ["一张镶嵌有珍贵宝石的特殊卡牌，容纳了灵界中关于“美”的概念。在被灵界生物带回现实后，能够化作不同种类的最为珍贵的美神收藏品。"] = "Особая карта, инкрустированная драгоценными камнями, содержащая понятие «красоты» Мира Духов. После того, как существа из Духовного мира вернули его в реальность, он может трансформироваться в различные виды самых ценных предметов коллекционирования Богини Красоты.",
    ["一整个夏天的阳光，都储存在了叶片里。"] = "В листьях хранится целое летнее солнце.",
    ["一旦进入战斗，厄运布偶就会伺机作祟。技能命中敌人时，布偶会附身到他身上，降低其防御与抗暴击，并随你切换目标转移。它回到你身上时，厄运便由你承担。"] = "Вступив в бой, Кукла Несчастья будет ждать возможности устроить беду. Когда умение поражает врага, кукла овладевает им, снижая его защиту и сопротивление критическому удару, а также перемещается при переключении целей. Когда оно вернется к вам, вы понесете несчастье.",
    ["一本诗集"] = "Сборник стихов",
    ["一枚不规则多面骰子，散发着金芒，触手温热，像有意识在内部缓缓翻动。握住它掷出时，仿佛命运在那一瞬主动倾身，眷顾即将到来的落点。"] = "Неправильная многогранная матрица, излучающая золотое сияние, теплая на ощупь, как будто внутри что-то медленно вращается вместе с сознанием. Когда держишь его и катишь, такое ощущение, будто судьба в этот момент активно наклоняется, благоприятствуя предстоящей точке приземления.",
    ["一枚不规则多面骰子，释放着幽暗的气息，暗紫色的光泽在棱线间流动。掷出时它会在空中停顿半息，像是在做一个决定。然后落向它挑中的那一面。"] = "Многогранный кубик неправильной формы, излучающий темную ауру с темно-фиолетовым блеском, струящимся между краями. При перекатке он замирает в воздухе на полвздоха, словно принимая решение. Затем он падает в ту сторону, которую выбрал.",
    ["一枚泛着星空色泽的古老钱币，能够通过精神体响应灵界、星空。上面镌刻着来自亚伯拉罕家族天使绘制的隐秘铭文，每一次使用如同开启一场星空漫游，能够为使用者带来旅途中的见闻与收获。"] = "Древняя монета с переливами звёздного неба, способная через духовное тело откликаться на Мир Духов и звёздное небо. На ней выгравированы тайные письмена, начертанные Ангелом рода Авраама; каждое использование подобно началу странствия по звёздам и приносит пользователю впечатления и находки в пути.",
    ["一枚记录着昔日团队荣誉的黄铜勋章。"] = "Латунная медаль, хранящая память о былых заслугах команды.",
    ["一柄能够剪裁命运丝线的锋利裁刀。掌握命运者也被命运左右，它的每一次剪裁都将带来未知的变化，愿好运永远与你相伴。"] = "Острый режущий инструмент, способный обрезать нити судьбы. Те, кто управляет судьбой, также находятся под ее контролем; каждый сделанный им разрез принесет неизвестные изменения. Пусть удача всегда будет с тобой.",
    ["一根手杖"] = "Трость",
    ["一根燃烧的火柴"] = "Горящая спичка",
    ["一段命运的支流，像凝固的晚霞，又像某条平行世界中永不熄灭的黎明。"] = "Приток судьбы, подобный застывшему вечернему закату или рассвету, что никогда не угаснет в одном из параллельных миров.",
    ["一片散发着微光的羽毛，轻若无物，隐约能感受到其中蕴含的神圣祝福。"] = "Перо, излучающее слабый свет, легкий как ничто, с тонким ощущением заключенного внутри божественного благословения.",
    ["一瓶盛放在玻璃瓶中的神秘液体。据说饮下它的人，能够暂时遗忘自己已经习得的能力，从而在命运的分岔路口，重新做出选择。"] = "Таинственная жидкость, содержащаяся в стеклянной бутылке. Говорят, что тот, кто его пьет, может на время забыть уже изученные способности, тем самым сделав новый выбор на перекрестке судеб.",
    ["一种特殊的材料，能够作为调配魔药的基底，此为众人觊觎的财富，无人不争。"] = "Особый материал, который может служить основой для приготовления зелий; это желанное всеми богатство, за которое все борются.",
    ["一种特殊的材料，能够作为调配魔药的基底，此为独属于你的胜利，无人可夺。"] = "Особый материал, который может служить основой для приготовления зелий; это только твоя победа, которую никто не сможет отнять.",
    ["一颗仍在跳动的火山，烫穿了持有者的理智。"] = "Всё ещё бьющийся вулкан, прожёгший разум своего обладателя насквозь.",
    ["一颗拳头大小的透明水晶球，内部仿佛封存着流动的光影。轻触水晶，那些优雅的舞步便会在脑海中重现，仿佛灵魂曾亲身经历过那场演出。而艺术的本质，便是将瞬间化为永恒。"] = "Прозрачный хрустальный шар размером с кулак, кажется, содержит внутри струящиеся свет и тени. Слегка коснитесь кристалла, и эти элегантные танцевальные па вновь возникнут в вашем сознании, как будто ваша душа испытала это представление лично. Сущность искусства – превратить мгновения в вечность.",
    ["一颗散发着紫色光芒的晶球，它象征着俱乐部的凝聚力，以及你的活跃与贡献。"] = "Хрустальный шар, излучающий фиолетовый свет; он символизирует сплоченность клуба, а также вашу активность и вклад.",
    ["七月成熟的果实自然渗出的汁液，带有轻微醉性与灵性扩散效果。"] = "Сок, естественно выделяющийся из плодов, созревающих в июле, обладает лёгким опьяняющим действием и эффектом распространения Духовности.",
    ["七月的馈赠，让灵性如酒般流淌。"] = "Дар июля заставляет Духовность течь, словно вино.",
    ["七种颜色在脑髓中旋转，永不停歇。"] = "Семь цветов вращаются в мозгу, никогда не останавливаясь.",
    ["三个月的凝视，镜中已沉淀出另一个完整的你。"] = "Три месяца Взгляда, и еще один полный ты устроился в зеркале.",
    ["三种形态，代表着流动、静止与凝固。"] = "Три формы, представляющие поток, неподвижность и затвердевание.",
    ["上等蓝宝石制成的袖钉，深邃的蓝色光芒犹如夜空星辰。"] = "Запонки из высококачественных сапфиров, светящиеся глубоким синим цветом, напоминающие звезды на ночном небе.",
    ["与人脉好感度达到上限以后，通过各玩法溢出的好感度转化而来，可在往事陈列馆商店中进行兑换。"] = "Получается путем конвертации благосклонности, перетекающей из различных игровых режимов после достижения максимальной благосклонности к человеку, и может быть обменена в магазине Прошлого выставочного зала.",
    ["与受诅水晶共生的微晶结构，能够同步并放大诅咒源的灵性频率。"] = "Микрокристаллическая структура, сосуществующая с проклятым кристаллом, способна синхронизировать и усиливать духовную частоту источника проклятия.",
    ["与古老灵感频率共振。"] = "Резонирует с древними частотами Вдохновения.",
    ["与誓约一起游玩各玩法获得的硬币，可以在誓约商店中进行兑换。"] = "Монеты, полученные за игру в различных режимах игры с Ковенантом, можно обменять в Магазине Ковенанта.",
    ["专用于裁启信封的短刀。珐琅柄身以金丝嵌制，华美而繁复。"] = "Короткий нож специально для вскрытия конвертов. Эмалированная ручка инкрустирована золотой нитью, великолепна и сложна.",
    ["世间万事，不过一场戏剧；你我都是戏中人，不必如此严肃。"] = "Все в мире — не более чем игра; мы с тобой оба актеры, не надо быть такими серьезными.",
    ["丝绸流淌着珠光，穿上它的你一定是晚会上耀眼的珍珠。"] = "Шелк, струящийся с перламутровым блеском; В нем вы наверняка станете ослепительной жемчужиной вечерней вечеринки.",
    ["两个土豆"] = "Две картофелины",
    ["两枚一大一小的厚实齿轮，可以用于火车升级"] = "Две толстые шестерни, одну большую и одну маленькую, можно использовать для модернизации поезда.",
    ["两种生命的混合，在血液中挣扎。"] = "Смесь двух жизней, борющихся в крови.",
    ["丧钟"] = "Похоронный Звон",
    ["丰收、富饶、生机勃勃。持有一段时间后背负诅咒，你死去时原地长出活化土地，为友方持续回血、提升攻击并免疫控制。但土地存在期间，你无法复活。"] = "Урожай, богатство и жизненная сила. Удерживая его в течение определенного периода времени, вы несете проклятие; когда вы умираете, активированная земля вырастает на месте, постоянно исцеляя товарищей по команде, увеличивая атаку и давая иммунитет к контролю. Но пока существует земля, вас невозможно воскресить.",
    ["临时测试用"] = "Для временного тестирования.",
    ["临时道具"] = "Временный предмет",
    ["乌托邦剧院"] = "Театр Утопии",
    ["乌托邦剧院中失控秘偶死亡后凝结形成的秘偶精粹，可在精粹收集者商人处换购商品。"] = "Эссенция марионетки, образовавшаяся после гибели марионетки, впавшей в Потерю Контроля, в Театре Утопии; можно обменять на товары у торговца-Коллекционера Эссенций.",
    ["乳白色的液体，接触空气后化作薄雾。"] = "Молочно-белая жидкость, при контакте с воздухом превращающаяся в легкую дымку.",
    ["二十二年，足够命运留下痕迹。"] = "Двадцати двух лет достаточно, чтобы судьба оставила след.",
    ["于【灾异巢穴】处召唤灾异先锋，将其击败可获得猩红遗物材料。灾异先锋实力强大，建议<Highlight>组队前往挑战</>。"] = "Вызовите авангард Бедствия в [Логово Бедствия]. Победа над ним даст материалы Алой реликвии. Авангард Бедствия силен; <Highlight> рекомендуется сформировать команду, чтобы бросить вызов </>.",
    ["五月庄园·城堡困难模式首通强者已加入队伍。这段被“母亲”注视的悲剧，终将宣告落幕。"] = "Сильнейший первого прохождения Майского поместья · Замка на сложном режиме присоединился к отряду. Эта трагедия под взором «Матери» наконец опустит занавес.",
    ["五月庄园·花园困难模式首通强者已加入队伍。在花径深处，誓将清断一切罪孽。"] = "Сильнейший первого прохождения Майского поместья · Сада на сложном режиме присоединился к отряду. В глубине цветочной тропы он клянется искоренить все грехи.",
    ["亚伯拉罕家族遗留的传送之杖。为目标刻下星痕标记，射程不足时消耗标记瞬移到位再出手，闪避之后还能追加一次瞬移。但触发越多，越可能失控迷路。"] = "Сотрудники Телепорта, оставленные семьей Авраама. Вырежьте звездочку на цели; когда дальность недостаточна, используйте метку, чтобы телепортироваться на позицию перед атакой, и вы можете добавить еще один телепорт после уклонения. Но чем сильнее он срабатывает, тем больше вероятность, что вы потеряете контроль и потеряетесь.",
    ["产自罗思德群岛第一大岛蓝山岛，此地矿藏众多，蓝山晶石是其中颇受欢迎的种类。"] = "Производится на острове Блу-Маунтин, самом большом острове архипелага Рорстед. В этом месте имеется множество месторождений полезных ископаемых, среди которых популярный сорт Blue Mountain Crystal.",
    ["产自鲁恩王国间海郡康斯顿城的某座矿山，尽管整座城市受战争摧残严重，但也因此拥有了大量含有灵性的材料。因矿山周围常有一些诡异的传闻，工人们只敢挖掘最外层的燧石。"] = "Добыто на одном из рудников города Констон в округе Мидси Королевства Лоэн. Хотя весь город сильно пострадал от войны, именно поэтому здесь оказалось много материалов, содержащих Духовность. Из-за странных слухов, часто ходящих вокруг рудника, рабочие осмеливаются добывать только кремень из самого верхнего слоя.",
    ["人们研究历史，以锚点习得真理。然而人们从历史学到的唯一真理就是：历史总在重蹈覆辙。"] = "Люди изучают историю, обретая истину через якоря. Однако единственная истина, которую люди извлекают из истории: история всегда повторяется.",
    ["人心是最喧嚣的寂静。"] = "Человеческое сердце – это самая крикливая тишина.",
    ["人心难测，但色彩从不说谎。"] = "Человеческое сердце трудно постичь, но цвета никогда не лгут.",
    ["人脉技能升级的消耗材料，可通过序列晋升获得。"] = "Расходный материал для повышения уровня Навыков связей, можно получить через повышение Последовательности.",
    ["仅在盛夏生长的草药，蕴含旺盛生命力，常用于增强体魄或生命相关配方。"] = "Травы, которые растут только в середине лета, содержат энергичное здоровье, часто используются для улучшения телосложения или в формулах, связанных со здоровьем.",
    ["仍在微微跳动，散发着不屈。"] = "Все еще слегка избиваясь, излучая неповиновение.",
    ["从“历史孔隙”中抽取的灵性之线，缠绕着无数可能的命运。"] = "Нити Духовности, извлечённые из «трещин истории», сплетающиеся с бесчисленными возможными судьбами.",
    ["从亲手击败的敌人身上取得，常用于血腥誓约或仇恨指向仪式。"] = "Получается от врага, побежденного собственными руками, часто используется в кровавых Заветах или ритуалах, направленных на ненависть.",
    ["从古老预言书中撕下的一页，因你的战绩而被重新书写。"] = "Страница, вырванная из древней книги пророчеств, переписанная благодаря вашим боевым достижениям.",
    ["从毛地黄中提取，具有强化心脏与生命节律的效果。"] = "Экстракт наперстянки, обладающий эффектом укрепления сердца и жизненных ритмов.",
    ["从灰雾之上飘落的空白书页，被命运的力量注入了灵性。当两份誓约产生共鸣时，隐藏的文字就会显现。"] = "Чистая страница, слетевшая из-за пределов серого тумана, наполнилась духовностью силой судьбы. Когда два обета вступают в резонанс, тайные письмена проявляются.",
    ["从灵界裂隙中收集的微风。"] = "Ветер, собранный из разлома в Мире Духов.",
    ["从秋水仙中提炼的高毒性精华，常用于抑制或扭曲生命力。"] = "Высокотоксичная эссенция, извлеченная из безвременника, часто используемая для подавления или искажения здоровья.",
    ["从纸根草中蒸馏萃取的液体，能够稳定精神，并增强对文字与符号的亲和力。"] = "Жидкость, добываемая из травы бумажного корня, способная стабилизировать разум и повысить чувствительность к тексту и символам.",
    ["从过去借取的力量，对相应的历史了解越详细，成功概率越大。"] = "Сила, заимствованная из прошлого: чем подробнее вы знаете соответствующую историю, тем выше вероятность успеха.",
    ["从迷雾中扎根，吸取虚幻与真实。"] = "Пуская корни в тумане, впитывать иллюзорное и реальное.",
    ["从迷雾树人本体剥离的核心根部，极具灵性。"] = "Стержневой корень, отделённый от тела Мглистого древня, обладает высокой Духовностью.",
    ["从阴影中剥落的一截锋利，仍能划破现实。"] = "Кусок резкости отделился от теней, все еще способный прорезать реальность.",
    ["从高温熔浆中自然冷却形成，保留部分火焰与大地属性。"] = "Он образуется в результате естественного охлаждения из высокотемпературной расплавленной жижи, сохраняя некоторые свойства огня и земли.",
    ["以太阳之名，净化一切不洁。"] = "Именем Солнца очисти всё нечистое.",
    ["以太阳途径象征物萃取的精油，可强化光、勇气与精神意志。"] = "Эфирное масло, извлеченное из символов Пути Солнца, способно усиливать свет, отвагу и силу воли.",
    ["以宝石为食的异常生物，体内残留强烈矿物灵性。"] = "Аномальное существо, питающееся драгоценными камнями; в его теле сохранилась мощная минеральная духовность.",
    ["以此为印，封存另一重容貌。"] = "С помощью этой печати запечатайте другое явление.",
    ["以白枫木板拼接打磨而成，造型朴实，适合日常书案收纳。"] = "Изготовленный путем сращивания и полировки белых кленовых досок, он прост и подходит для ежедневного хранения на столе.",
    ["以空想为墨，以灵感为引，凡落笔者，皆成故事。"] = "Фантазия — чернила, вдохновение — проводник: всё, что выведет перо, станет историей.",
    ["仪式是人与神秘之间的契约，而契约需要见证。"] = "Ритуал — это договор между человеком и тайной, а договору нужны свидетели.",
    ["优质干草和萝卜足以让疲惫的马儿们再次充满斗志，嚼嚼嚼！"] = "Хорошего сена и моркови достаточно, чтобы усталые лошадки снова наполнились боевым духом. Хрум-хрум-хрум!",
    ["优质的羊绒触感如云朵般柔软，诠释贵族生活的低调与奢华。"] = "Высококачественный кашемир мягкий, как облако, воплощая сдержанную роскошь аристократической жизни.",
    ["会改变周围植物的生长方式。"] = "Изменится характер роста окружающих растений.",
    ["传说由你铸就，此令为证。用于嘉奖非凡者在%s的势力战中的英勇表现。"] = "Легенды созданы вами; пусть этот приказ будет доказательством. Используется для награды за героические действия Потусторонние в войнах фракций %s.",
    ["伦纳德·米切尔的历史投影，重现了原主的形态与部分能力。"] = "Историческая проекция Леонарда Митчелла, воссоздающая форму и частичные способности оригинала.",
    ["伴随陨落星体形成的高灵性结晶。"] = "Кристаллы высокой духовности, образовавшиеся при падении звезды.",
    ["体内藏着一片凝固的星空。"] = "В корпусе скрыто застывшее звездное небо.",
    ["佛尔思·沃尔的历史投影，重现了原主的形态与部分能力。"] = "Историческая проекция стены Форс, воссоздающая форму и частичные способности оригинала.",
    ["你几乎能感到雪松在嘴里发芽破土，微苦的木香余韵在唇舌之间。"] = "Вы почти можете почувствовать, как кедр прорастает и пробивается сквозь почву во рту, а между губами и языком остается слегка горьковатый древесный привкус.",
    ["你已集齐所有散落的篇章。这些知识在你脑中拼接完整，构筑起一个比任何史书都更真实的罗塞尔·古斯塔夫。"] = "Вы собрали все разрозненные главы. Эти знания складываются в вашем сознании, создавая Розель Густав, более реальную, чем любая книга по истории.",
    ["你的名称传遍世界，属于团长的荣耀加冕于你。"] = "Твоё имя разносится по всему миру, и слава, принадлежащая лидеру, коронует тебя.",
    ["你的旗帜屹立不倒，你的团队凝聚一心。"] = "Твой флаг стоит непреклонно, а твоя команда сплочена как единое целое.",
    ["使用<Highlight>补领凭券</>可在补领商店内购买错过玩法的补领礼盒，获得部分玩法奖励。\n获得发票单据时可同时获得补领凭券，补领凭券最多储存50000个。"] = "Используйте <Highlight>купоны компенсации</> в магазине компенсаций, чтобы приобретать наборы за пропущенные активности и получать часть их наград.\nКупоны компенсации выдаются одновременно с квитанциями; максимум можно накопить до 50 000 купонов.",
    ["使用南大陆的硬质玉米，压制、焙烤成金黄脆片，香酥可口。"] = "Использование твердой кукурузы с Южного континента, прессованной и обжаренной в хрустящие золотистые чипсы, ароматные и вкусные.",
    ["使用后下一次投掷必定出现大失败。本效果与【命运之吻】互斥，以最后使用者为准。该效果不影响特殊定制投骰玩法的结果。"] = "После использования ваш следующий бросок гарантированно окажется критическим провалом. Этот эффект является взаимоисключающим с эффектом «Поцелуй судьбы»; эффект последнего пользователя имеет приоритет. Этот эффект не влияет на результаты игры в специальные игровые кости.",
    ["使用后下一次投掷必定出现大成功。本效果与【厄数之骰】互斥，以最后使用者为准。该效果不影响特殊定制投骰玩法的结果。"] = "После использования ваш следующий бросок гарантированно будет успешным. Этот эффект является взаимоисключающим с эффектом [Кости несчастья]; эффект последнего пользователя имеет приоритет. Этот эффект не влияет на результаты игры в специальные игровые кости.",
    ["使用后可以变身成为卷毛狒狒，最多持续1分钟，主动使用技能会解除变身状态。"] = "После использования вы можете превратиться в кудрявого павиана на срок до 1 минуты. Активное использование навыка отменит состояние трансформации.",
    ["使用后可以变身成为小象玩偶，最多持续1分钟，主动使用技能会解除变身状态。"] = "При использовании превращает в плюшевого слонёнка на срок до 1 минуты. Применение любого навыка отменяет превращение.",
    ["使用后可以变身成为幽影，最多持续1分钟，主动使用技能会解除变身状态。"] = "После использования вы можете превратиться в Тень на срок до 1 минуты. Активное использование навыка отменит состояние трансформации.",
    ["使用后可以变身成为骑士，最多持续1分钟，主动使用技能会解除变身状态。"] = "После использования вы можете превратиться в Рыцаря на срок до 1 минуты. Активное использование навыка отменит состояние трансформации.",
    ["使用后可以将动捕动作保存至社交动作。"] = "После использования позволяет сохранить захваченную анимацию в список социальных действий.",
    ["使用后可以转动幸运大转盘。"] = "После использования вы можете вращать Lucky Big Wheel.",
    ["使用后可以选择任意一个已拥有的培养度更低的橙色秘偶，与秘偶<Highlight>异化赛琳娜</>交换培养度。"] = "После использования можно выбрать любую имеющуюся оранжевую марионетку с более низким уровнем развития и обменяться уровнем развития с марионеткой <Highlight>Отчуждённая Селена</>.",
    ["使用后可在歌剧魅影玩法中表演<Highlight>魅影动作·优雅回眸</>"] = "После использования вы можете выполнить действие <Highlight>Phantom: Элегантный взгляд назад</> в игровом процессе Phantom of the Opera.",
    ["使用后可在歌剧魅影玩法中表演<Highlight>魅影动作·俏皮模式</>"] = "Используйте, чтобы получить возможность исполнить <Highlight>действие Призрака: Игривый стиль</> в режиме «Призрак оперы»",
