    ["使用后解锁投骰结算.金"] = "Открывает поселение на кубиках: золото при использовании.",
    ["使用后释放巨人化技能，自身体型在30秒内变大1.5倍。"] = "После использования отпустите навык «Гигантификация», увеличивая свой размер в 1,5 раза на 30 секунд.",
    ["使用后释放执火者技能，在30秒内可以手持火把移动，冲刺和跳跃可以打断手持火炬状态。"] = "После использования отпустите навык «Хранитель огня». Вы можете двигаться, удерживая факел в течение 30 секунд. Спринт и прыжки прервут состояние удержания факела.",
    ["使用后，可以让商队立刻到达本次行程的终点"] = "После использования караван мгновенно прибудет в конечную точку текущего маршрута",
    ["使用后，回复20点贸易战争玩法中的商队体力"] = "После использования восстанавливает 20 ед. выносливости каравана в режиме «Торговая война»",
    ["使用后，对使用者周围至多12名玩家（含使用者本人）各恢复一部分理智值，对失控状态的玩家无效。"] = "После использования восстанавливает часть рассудка не более чем 12 игрокам вокруг (включая самого использующего). Не действует на игроков в состоянии Потери Контроля.",
    ["使用后，开启任务“<Highlight>【神降】荣光织造·灵骑</>”，开启任务不会消耗该道具。\n可交易的该道具上架<Highlight>商城—交易所</>时，推荐售价<Highlight>40000万苏勒</>。"] = "После его использования начните миссию «<Highlight>[Божье нисхождение] Славное плетение·Духовная езда</>». При запуске миссии этот реквизит не будет расходоваться. \n Когда торгуемый предмет попадает на полки <Highlight> Mall-Exchange </>, рекомендуемая цена продажи составляет <Highlight> 400 миллионов сулеров </>.",
    ["使用后，开启任务“<Highlight>【神降】荣光织造·羽翼</>”，开启任务不会消耗该道具。\n可交易的该道具上架<Highlight>商城—交易所</>时，推荐售价<Highlight>40000万苏勒</>。"] = "После использования открывается задание «<Highlight>[Нисхождение бога] Ткачество славы · Крылья</>»; выполнение задания не расходует этот предмет.\nЕсли этот обмениваемый предмет выставляется на <Highlight>Магазин — Биржу</>, рекомендуемая цена продажи — <Highlight>400 000 000 Соль</>.",
    ["使用后，开启任务“【神降】荣光织造·盛装”。"] = "После использования начинается задание «[Нисхождение бога] Плетение славы: Парадный наряд».",
    ["使用后，立即恢复使用者一部分理智值。"] = "После использования немедленно восстанавливает часть здравомыслия пользователя.",
    ["使用后，立即降低使用者一部分理智值。"] = "После использования немедленно уменьшает часть здравомыслия пользователя.",
    ["使用后，解锁专属投骰背景皮肤<Highlight>【伦纳德·米切尔-紫藤絮语】</>。\n也许，命运和诗篇一样，都经不起逐字推敲。"] = "После использования разблокируйте эксклюзивный фоновый скин для игральных костей <Highlight> [Леонард Митчелл-Глициния Шепот] </>. \nПожалуй, судьба, как и поэзия, не выдерживает дословной проверки.",
    ["使用后，解锁专属投骰背景皮肤<Highlight>【命运赌桌】</>。\n在一切尚未尘埃落定之前，赌桌之上无人知晓成败。"] = "При использовании открывает эксклюзивный облик для броска костей <Highlight>【Игорный стол судьбы】</>.\nПока пыль не улеглась, за игорным столом никто не знает исхода.",
    ["使用后，解锁专属骰子皮肤<Highlight>【晨曦之骰】</>。\n一颗覆盖着晨曦光辉的骰子。掷出它，也许命运更偏爱你这一隅光芒。"] = "После использования разблокируйте эксклюзивный скин для кубиков <Highlight> [Кости Рассвета] </>. \nКости, покрытые светом утреннего света. Брось, может судьба предпочтет твой уголок света.",
    ["使用后，解锁专属骰子皮肤<Highlight>【暗夜之骰】</>。\n一颗沾染着夜幕色泽的骰子。掷出它，也许会有其他存在于暗处替你拨转命运。"] = "После использования разблокируйте эксклюзивный скин для кубиков <Highlight> [Dark Night Dice] </>. \nКости, окрашенные в цвет ночи. Брось его, и во тьме могут оказаться другие существа, способные изменить твою судьбу.",
    ["使用后，解锁专属骰子皮肤<Highlight>【豪掷之金】</>。\n以极致的工艺打磨边缘至璨金，令每次投掷时，都闪烁着流光溢彩的色泽，是实力与品味最耀眼的证明。"] = "Используйте, чтобы разблокировать эксклюзивный облик костей <Highlight>【Золотой бросок】</>.\nГрани, отполированные с высочайшим мастерством до ослепительного золотого блеска, переливаются всеми красками при каждом броске, служа ярчайшим свидетельством вашего мастерства и вкуса.",
    ["使用琉璃吹制工艺，造型华美。适用于每一个值得庆祝的时刻。 "] = "Изготовлено с использованием мастерства выдувания стекла и имеет великолепный дизайн. Подходит для каждого момента, который стоит отпраздновать.",
    ["使用终结技能后，能在挥舞击打中附加风刃效果，提升移速、破防、技能增强。同时，你也会因为这位歌者的糟糕歌喉，间歇性地获得禁锢、沉默、属性降低的负面效果。"] = "После использования завершающего навыка ваши удары получают эффект ветряного клинка: повышаются скорость передвижения, прорыв защиты и усиление навыков. Однако из-за ужасного голоса этого певца вы периодически получаете негативные эффекты: заточение, молчание и снижение характеристик.",
    ["使用该道具后，瑞尔比伯副本非共享次数增加1次，五月外庭共享次数增加1次。"] = "После использования этого предмета неразделяемые попытки прохождения подземелья Райэль Бибер увеличиваются на 1, а общие попытки прохождения Майского внешнего двора увеличиваются на 1.",
    ["保留着猎杀的本能记忆。"] = "Сохранение инстинктивной памяти об Охоте.",
    ["信仰的温度，仍残留在器物表面。"] = "Тепло веры все еще сохраняется на поверхности предмета.",
    ["俱乐部宣战期间，<Highlight>会长、外交官、理事</>可在霍纳奇斯山脉使用该道具，使用该道具将向<Highlight>地图内的本俱乐部成员</>发起集结。使用后，将以俱乐部为单位，使该道具全部进入 <Highlight>360</> 秒冷却。"] = "Во время войны клубов <Highlight>глава, дипломат или советник</> могут использовать этот предмет в горах Хорнацис, чтобы объявить сбор <Highlight>членов своего клуба на карте</>. После использования предмет уходит на общую перезарядку для всего клуба длительностью <Highlight>360</> сек.",
    ["俱乐部活跃值，可以参与俱乐部活跃津贴任务获得。"] = "Очки клубной активности, которые можно получить, участвуя в квестах Club Activity Allowance.",
    ["像老友的拥抱，粗砺质感里包裹着细腻的灵魂。"] = "Словно объятие старого друга: за грубой текстурой скрывается утонченная душа.",
