    ["脱帽时微颔首， 有礼帽懂礼貌。"] = "Легкий кивок при снятии шляпы; цилиндр показывает хорошие манеры.",
    ["腐烂的流星"] = "Гниющий метеор",
    ["自定义方案解锁所需的材料，可在商城购买获得。"] = "Материалы, необходимые для разблокировки пользовательских схем; можно приобрести в магазине.",
    ["自花叶蒸馏而得，香气蕴含安神与振奋双重波动。"] = "Созданный из цветов и листьев, аромат содержит двойные вибрации: успокаивающие разум и поднимающие дух.",
    ["自迷雾树人体内流出的液体，带有遮蔽与迷惑效果。"] = "Жидкость, вытекающая изнутри туманного энта, оказывает экранирующий и сбивающий с толку эффект.",
    ["自邪视器官溃裂处渗出，带有极强侵蚀性与梦境污染特质。"] = "Истекает из разорванного органа сглаза, с чрезвычайно сильными характеристиками эрозии и порчи снов.",
    ["致命的甘甜，是通往超凡的窄门。"] = "Смертельная сладость — узкая дверь к необыкновенному.",
    ["致幻的汁液，分不清现实与梦境。"] = "Галлюциногенный сок, неспособный отличить реальность от снов.",
    ["色彩变幻，扰乱感知。"] = "Цвет меняется, нарушая восприятие.",
    ["色泽金黄的货币，正面印刻有戴王冠的留着两撇小胡子、严肃古板的乔治三世头像，是鲁恩王国货币体系中最高级的货币。"] = "Валюта золотистого цвета, с выгравированным на лицевой стороне портретом серьезного и строгого Георга III с короной и усами; это валюта высшего уровня в денежной системе Королевства Лоен.",
    ["花瓣边缘自然呈现金色的太阳花，象征太阳途径的祝福与庇护。"] = "Подсолнух с естественными золотыми краями лепестков, символизирующий благословение и прибежище Солнечного пути.",
    ["花瓣间沉睡的面容，是某个灵魂的倒影。"] = "Лицо, спящее между лепестками, – отражение души.",
    ["苍白的死亡"] = "Бледная смерть",
    ["苏茜的历史投影，重现了原主的形态与部分能力。"] = "Историческая проекция Сьюзи, воссоздающая форму и частичные способности оригинала.",
    ["苦得让人清醒。"] = "Достаточно горько, чтобы отрезвить.",
    ["苦涩的粉末，能麻木痛觉。"] = "Горький порошок, притупляющий боль.",
    ["英雄内城1材料"] = "Герой Внутреннего Города 1 Материал",
    ["英雄内城2材料"] = "Материал «Герой Внутренний город 2»",
    ["英雄内城3材料"] = "Герой Внутреннего Города 3 Материал",
    ["英雄外城1材料"] = "Материалы Внешнего города героев 1",
    ["英雄外城2材料"] = "Материалы Внешнего города героев 2",
    ["英雄外城3材料"] = "Материалы Внешнего города героев 3",
    ["草木的呼吸化作了液态的静谧，文字在其中沉睡。"] = "Дыхание растений и деревьев превратилось в жидкую тишину, в которой уснули слова.",
    ["荣耀之证"] = "Свидетельство славы",
    ["莉莉丝指环"] = "Кольцо Лилит",
    ["获得10个<Highlight>凯旋徽章</>。"] = "Получите 10 значков триумфа <Highlight>T</>.",
    ["获得1个<Highlight>凯旋法典·神座之争</>和<Highlight>25个凯旋徽章</>。"] = "Получено: 1 шт. <Highlight>Кодекс триумфа: Битва за Престол</> и <Highlight>25 знаков триумфа</>.",
    ["获得1个<Highlight>战勋之书·神座之争</>和15个<Highlight>凯旋徽章</>。"] = "Получите 1 <Highlight>Книгу военных заслуг — Битва за Трон Божий</> и 15 <Highlight>Tтриумфальных значков</>.",
    ["获得20个<Highlight>凯旋徽章</>。"] = "Получите 20 значков триумфа <Highlight>T</>.",
    ["获得XXX技能"] = "Получить XXX навык",
    ["获得一次额外复活次数，购买时立刻生效"] = "Получите один дополнительный шанс на воскрешение, вступающий в силу сразу после покупки.",
    ["获得持续<Highlight>30</>天的福音券运势解读，以及<Highlight>人脉快速互动次数增加</>、<Highlight>玩法货币获取效率提升</>、<Highlight>自定义传送信标</>、<Highlight>活力上限增加</>等特权。\n每日登录可获得<Highlight>100</>绑定金镑以及<Highlight>愚者馈赠</>，累积登录还可额外获得更多<Highlight>活力方糖</>。\n请注意，只有当前愚者福音剩余天数<Highlight>小于等于150天</>时，才可使用道具。"] = "Дарует толкование судьбы по купону Евангелия на <Highlight>30</> дн., а также привилегии: <Highlight>больше попыток быстрого взаимодействия со связями</>, <Highlight>повышенная эффективность получения игровой валюты</>, <Highlight>настраиваемые маяки телепортации</> и <Highlight>увеличенный запас бодрости</>.\nЗаходите в игру каждый день, чтобы получать <Highlight>100</> привязанных золотых фунтов и <Highlight>Подарок Шута</>; за суммарный вход выдаются дополнительные <Highlight>кубики сахара бодрости</>.\nОбратите внимание: предмет можно использовать, только если до окончания действия текущего Евангелия Шута осталось <Highlight>не более 150 дней</>.",
    ["获得该神奇物品后，将获得占卜家序列的扮演技能。\n一条银质链子，末端悬挂着磨圆的陨铁碎片，中间镶嵌一颗从古代遗迹中取出的水晶。"] = "Получив этот магический предмет, вы обретете навыки гадания. \n Серебряная цепочка, на конце которой свисают округлые фрагменты метеорита, а посередине — кристалл, взятый из древних руин.",
    ["获得该神奇物品后，将获得占星人序列的扮演技能。\n一颗暗蓝色的水晶球，其内部漂浮着不断运动的星光与微弱云雾。即使闭眼也能感受到它的微弱脉动，像在呼吸。"] = "Заполучив этот мистический предмет, вы освоите навык отыгрыша Последовательности Астролога.\nХрустальный шар глубокого синего оттенка, внутри которого вечно кружат крупицы звездного света и легкая туманная дымка. Даже закрыв глаза, можно ощутить его едва заметную пульсацию — словно тихое дыхание.",
    ["获得该神奇物品后，将获得太阳神官序列的扮演技能。\n刻印太阳徽记的金片，可在祈祷中释放圣焰。"] = "После получения этого мистического предмета вы откроете навык Отыгрыша Последовательности «Жрец Солнца».\nЗолотая пластинка с выгравированной эмблемой Солнца способна извергать святое пламя во время молитвы.",
    ["获得该神奇物品后，将获得学徒序列的扮演技能。\n一把古铜钥匙，插入任何门锁时，门另一侧会通往随机位置。"] = "Получив этот мистический предмет, вы откроете навык отыгрыша роли Последовательности Ученика.\nСтаринный бронзовый ключ: будучи вставленным в любой дверной замок, он заставляет дверь с противоположной стороны вести в случайное место.",
    ["获得该神奇物品后，将获得小丑序列的扮演技能。\n一只由深紫与金色布料拼接而成的奇形圆篓，表面绣着歪曲的笑脸与象征混乱的螺旋纹。"] = "Получив этот мистический предмет, вы откроете навык отыгрыша роли Последовательности Клоуна.\nПричудливый круглый короб, сшитый из тёмно-фиолетовой и золотой ткани, на поверхности которого вышиты кривая ухмылка и спиральный узор, символизирующий хаос.",
    ["获得该神奇物品后，将获得巫师序列的扮演技能。\n刻有繁复符文的圆盘，可用于进行仪式。"] = "При получении этого запечатанного предмета дает навык отыгрыша Последовательности Чернокнижника.\nДиск с высеченными замысловатыми рунами, используемый для проведения ритуалов.",
    ["获得该神奇物品后，将获得心理医生序列的扮演技能。\n一支细长金属笔，书写在空气中的符号会进入目标精神，调整其情绪状态。"] = "Получив этот волшебный предмет, вы приобретете ролевые навыки психолога. \nТонкая металлическая ручка, символы, написанные в воздухе, проникнут в душу цели и отрегулируют ее эмоциональное состояние.",
    ["获得该神奇物品后，将获得戏法大师序列的扮演技能。\n看似普通的黑木方盒，却带有半透明的光泽，盒面镶嵌着七颗细小的彩色宝石。从盒中取出的物品总是带着不真实的感觉，偶尔会在空气中化为幻象。盒子整体散发淡淡香气，但有时香气会变为令人困惑的金属味。"] = "Получив этот мистический предмет, вы откроете навык отыгрыша роли Последовательности Трикстера.\nС виду обычная квадратная шкатулка из чёрного дерева, отливающая полупрозрачным блеском, крышка которой инкрустирована семью крошечными цветными драгоценными камнями. Предметы, извлечённые из неё, всегда кажутся нереальными и порой растворяются в воздухе призрачной иллюзией. Шкатулка источает тонкий аромат, который иногда сменяется тревожным металлическим привкусом.",
    ["获得该神奇物品后，将获得战士序列的扮演技能。\n一双厚重铁靴，踩击地面时可制造震动与裂纹。"] = "После получения этого запечатанного предмета дает навык отыгрыша Пути Воина.\nПара тяжелых железных сапог, топот которых вызывает сотрясения и трещины в земле.",
    ["获得该神奇物品后，将获得格斗学者序列的扮演技能。\n一副古铜色眼镜，镜片呈淡金色，边框刻有猎隼和锋利爪子的浮雕。佩戴时视野会略微缩窄，但所有人影似乎被分割成不同色块与流动线条。"] = "Получив этот мистический предмет, вы обретаете навык Лицедейства Последовательности «Учёный боя».\nОчки цвета античной бронзы со светло-золотистыми линзами; на оправе выгравированы рельефные изображения сокола и острых когтей. При ношении поле зрения слегка сужается, однако все силуэты людей словно распадаются на цветовые пятна и струящиеся линии.",
    ["获得该神奇物品后，将获得格斗家序列的扮演技能。\n能增加力量与爆发的护腕。"] = "При получении этого запечатанного предмета дает навык отыгрыша Последовательности Борца.\nНаручи, увеличивающие силу и взрывную мощь.",
    ["获得该神奇物品后，将获得歌颂者序列的扮演技能。\n金色鸟羽，握在手中时会散发温暖光辉。"] = "Заполучив этот мистический предмет, вы освоите навык отыгрыша Последовательности Песнопевца.\nЗолотое птичье перо, мягко согревающее ладонь ровным теплым сиянием.",
    ["获得该神奇物品后，将获得武器大师序列的扮演技能。\n腰带上有微型符文，可在表演时幻化出各种武器。"] = "После получения этого волшебного предмета вы получите навыки игры в последовательности «Мастер оружия». \n На поясе имеются микроруны, которые во время выступлений могут трансформироваться в различное оружие.",
    ["获得该神奇物品后，将获得祈光人序列的扮演技能。\n一个古老手灯，可将目标身上覆盖淡金光辉。"] = "После получения этого мистического предмета вы откроете навык отыгрыша Последовательности Молящегося Свету.\nСтаринный ручной фонарь, окутывающий цель бледно-золотистым сиянием.",
    ["获得该神奇物品后，将获得窥秘人序列的扮演技能。\n折叠的小纸片，在手中会显示隐秘信息。"] = "После получения этого запечатанного артефакта вы откроете навык отыгрыша Последовательности Жреца Тайн.\nСложенный клочок бумаги, на котором при прикосновении проявляются сокрытые сведения.",
    ["获得该神奇物品后，将获得观众序列的扮演技能。\n一面小巧铜镜，映照出的不是人的外貌，而是其心情对应的色彩与光晕形态。"] = "После получения этого волшебного предмета вы приобретете навыки ролевой игры в зрительном ряду. \nНебольшое бронзовое зеркало отражает не внешность человека, а цвет и форму нимба, соответствующие его настроению.",
    ["获得该神奇物品后，将获得读心者序列的扮演技能。\n暗色戒指，佩戴时，可听到目标心中正在想的情绪内容。"] = "После получения этого мистического предмета вы откроете навык отыгрыша Последовательности Читателя Мыслей.\nТёмное кольцо; при ношении позволяет слышать эмоции и переживания цели.",
    ["获得该神奇物品后，将获得魔术师序列的扮演技能。\n细长的纸片折叠成的人形，眼部用墨水画出漩涡符号。"] = "Получив этот мистический предмет, вы откроете навык отыгрыша Последовательности Фокусника.\nЧеловеческая фигурка, сложенная из тонкой полоски бумаги, с нарисованными чернилами символами водоворота вместо глаз.",
    ["萃取天然玫瑰花香，在每一个季节盛放。"] = "Экстракт натурального аромата розы, цветущей в любое время года.",
    ["萃取自糖枫树，色泽金黄，糖液丝滑，清爽草木甜，是热松饼的黄金搭档。"] = "Извлечен из сахарного клена, золотистого цвета, шелковистый сироп с освежающей древесной сладостью; это идеальный компаньон для горячих блинов.",
    ["蒸汽与机械的浪潮中，谁能触及非凡？历史和黑暗的迷雾里，又是谁在耳语？"] = "Кто в приливе пара и машин способен коснуться потустороннего? Кто шепчет в тумане истории и мрака?",
    ["蒸汽文明的火漆印章，罗塞尔大帝改革中法律文书与蒸汽技术并重，这枚火漆印章就是最好的凭证。"] = "Восковая печать паровой цивилизации. Во время реформ императора Розелле юридическим документам придавалось такое же значение, как и паровой технологии, и эта сургучная печать — лучшее тому подтверждение.",
    ["蓝莓与草莓携手跳一曲华尔兹，旋转出酸甜滋味。来，抹面包试试吧！"] = "Черника и клубника вместе танцуют вальс, создавая кисло-сладкий вкус. Давай, попробуй намазать его на хлеб!",
    ["蕴含一定灵质的矿石，可用于置换装备历史词条。"] = "Руда, содержащая духовность; используется для замены прежних свойств снаряжения.",
    ["蕴含不同特性的自然之水，用于对应不同属性的仪式基底。"] = "Природная вода с различными характеристиками используется в качестве основы для ритуалов, соответствующих различным атрибутам.",
    ["蕴含光辉与灵界力量的树木汁液，用于净化或构建灵性通道。"] = "Древесный сок, содержащий свет и силу Духовного мира, используется для очищения или создания духовных каналов.",
    ["蕴含冷血与狩猎本能的超凡血液，能增强仪式的侵略性与隐匿性。"] = "Необыкновенная кровь, содержащая хладнокровность и охотничьи инстинкты, способные усилить агрессию и сокрытие ритуалов.",
    ["蕴含多重伪装信息的超凡血液，能短暂改变自身或物品的气息。"] = "Необыкновенная кровь, содержащая множество камуфляжных сообщений, которые могут на короткое время изменить ауру человека или объекта.",
    ["蕴含月光之力与强大撕扯能力的超凡肢体，兼具神圣与狂暴。"] = "Необыкновенные конечности, обладающие силой лунного света и сильной разрывной способностью, обладающие одновременно божественностью и берсерком.",
    ["蕴含海量知识与疯狂呓语的超凡大脑，是智慧与失控的结合体。"] = "Необыкновенный мозг, содержащий огромные знания и сумасшедший шепот, сочетание мудрости и потери контроля.",
    ["蕴含着旺盛生命力与自然亲和力的液体，是极佳的治疗与催生媒介。"] = "Жидкость содержит сильную жизненную силу и природное сродство и является превосходной средой для лечения и родов.",
    ["蕴含神秘力量的灯，点亮后可叩开历史回廊的大门。"] = "Лампа, наполненная таинственной силой; однажды зажженный, он может открыть дверь в коридор истории.",
    ["蕴含迎接光明勇气的核心骨骼，可用于驱散恐惧或强化意志。"] = "Сердцевинные кости содержат смелость приветствовать свет, который можно использовать, чтобы рассеять ужас или укрепить волю.",
    ["融合了可可的微苦与奶油的绵密，比起酒精更像一道甜点。"] = "Сочетая легкую горчинку какао со сливочным маслом, он больше похож на десерт, чем на алкоголь.",
    ["蠕动的饥饿"] = "Ползучий Голод",
    ["血之花"] = "Кровавый цветок",
    ["血族始祖亲手锻造的永恒满月。提升自己与队友的战斗技能等级，并强化秘偶，即使技能冷却中也有概率强制召出。代价是每一次强召，都会吞噬你的生命。"] = "Вечная полная луна, выкованная предком вампиров. Повышает уровень боевых навыков себя и товарищей по команде, а также усиливает марионетку; даже если умение находится на перезарядке, существует вероятность принудительного призыва. Цена в том, что каждый принудительный призыв поглотит ваше здоровье.",
    ["血液在试管中不断变换颜色。"] = "Кровь в пробирке постоянно меняет цвет.",
    ["血液在试管中扭曲了光线。"] = "Кровь искажала свет в пробирке.",
    ["衣摆掠过街灯时，总有些秘密在褶皱里沙沙作响。"] = "Когда подол платья проходит мимо уличного фонаря, в складках всегда шуршат тайны.",
    ["表演者+750分，并显示灯牌"] = "Исполнитель: +750 очков, отображается световая вывеска",
    ["被污染的光明，阴影在边缘蔓延。"] = "Испорченный свет, тени, расплывающиеся по краям.",
    ["装备强化所需的材料，使用该材料可以将装备最高强化到赛季「大帝的归来」的精炼度上限。"] = "Материалы, необходимые для усиления оборудования. С помощью этого материала можно усилить экипировку до предела усовершенствования сезона «Возвращение Императора».",
    ["装备提炼而成的纯净灵质结晶，散发着明亮的光芒，宛如一颗微小而强大的星辰。"] = "Чистый духовный кристалл, очищенный от оборудования, излучающий яркий свет, подобный крошечной, но мощной звезде.",
    ["装备重塑所需的材料。重塑后，将对装备的随机词条的词条数和所有词条的属性类型、数值重新进行一遍随机。"] = "Материал, необходимый для перековки снаряжения. После перековки количество случайных аффиксов снаряжения, а также тип и значение параметров каждого аффикса будут переопределены случайным образом.",
    ["西迦特昂以邓恩戴莉为原型撰写的童话故事第一节。"] = "Первая глава сказки Сиги Танг по мотивам Данна и Дейли.",
    ["西迦特昂以邓恩戴莉为原型撰写的童话故事第三节。"] = "Третья часть сказки, написанная Сигатеоном по мотивам Данна Дейли.",
    ["西迦特昂以邓恩戴莉为原型撰写的童话故事第二节。"] = "Вторая часть сказки Сики Трон, написанной по мотивам историй о Дэнне и Дейли.",
    ["西迦特昂以邓恩戴莉为原型撰写的童话故事第五节。"] = "Пятая глава сказки Сиги Танг по мотивам Данна и Дейли.",
    ["西迦特昂以邓恩戴莉为原型撰写的童话故事第四节。"] = "Четвертая глава сказки Сиги Танг по мотивам Данна и Дейли.",
    ["西迦特昂以邓恩戴莉为原型撰写的童话故事，他们在童话里拥有美好幸福的结局。"] = "Сказка, написанная Сигой Теангом по мотивам Данна и Дейли, в которой у них красивый и счастливый конец.",
    ["角质纤维内，存有追踪与锁定目标的自然灵性。"] = "Внутри роговых волокон заключена природная духовность, служащая для выслеживания и захвата цели.",
    ["触之可迅速阻滞精神流动。"] = "Прикосновение быстро блокирует течение духовности.",
    ["触摸时能感受到野性的脉动。"] = "Может чувствовать пульс дикости при прикосновении.",
    ["触碰时，皮肤会不自觉地蠕动。"] = "При прикосновении кожа непроизвольно вздрагивает.",
    ["记住你只是在扮演"] = "Помни: ты лишь играешь роль",
    ["记住朋友，在廷根……当你拿到这个的时候，你就已经不是“好市民”，而是我们的一员了。欢迎来到真实的秩序世界，现在，来领赏，或者滚蛋。"] = "Помни, друг, в Тингене... когда ты получишь это, ты уже не «добрый гражданин», а один из нас. Добро пожаловать в мир истинного порядка. А теперь забирай свою награду или уходи.",
    ["记住，你只是在扮演。"] = "Помните, вы просто притворяетесь.",
    ["记录下火车行驶的里程，它见证着每一笔交易，也见证着一位铁路大亨如何诞生。"] = "Фиксирует пройденный поездом путь — он свидетель каждой сделки и того, как рождается железнодорожный магнат.",
    ["记录了其他非凡者成长经验的特殊能量魔水，使用后可快速经历其他强大非凡者的成长之路，让自己迅速度过弱小期，获得10000点经验"] = "Особое энергетическое зелье, записывающее опыт развития других Потусторонних. После использования можно быстро испытать путь роста других могущественных Потусторонних, позволяя себе быстро пройти период слабости и получить 10 000 очков опыта.",
    ["记录着他人不愿被知晓的记忆。"] = "Запись воспоминаний, о которых другие не хотят знать.",
    ["记录着晋升至序列3的魔药配方的羊皮纸，消化进度达到一定程度后由黑荆棘安保公司提供给活跃成员。"] = "Пергамент с формулой зелья для перехода к Последовательности 3, предоставляемый Охранной компанией Чёрный Чертополох активным членам после достижения определенного уровня пищеварения.",
    ["记录着晋升至序列4的魔药配方的羊皮纸，消化进度达到一定程度后由黑荆棘安保公司提供给活跃成员。"] = "Пергамент с формулой зелья для перехода к Последовательности 4, предоставляемый Охранной компанией Чёрный Чертополох активным членам после достижения определенного уровня пищеварения.",
    ["记录着晋升至序列5的魔药配方的羊皮纸，消化进度达到一定程度后由黑荆棘安保公司提供给活跃成员。"] = "Пергамент с формулой зелья для перехода к Последовательности 5, предоставляемый Охранной компанией Чёрный Чертополох активным членам после достижения определенного уровня пищеварения.",
    ["记录着晋升至序列6的魔药配方的羊皮纸，消化进度达到一定程度后由黑荆棘安保公司提供给活跃成员。"] = "Пергамент с формулой зелья для перехода к Последовательности 6, предоставляемый Охранной компанией Чёрный Чертополох активным членам после достижения определенного уровня пищеварения.",
    ["记录着晋升至序列7的魔药配方的羊皮纸，消化进度达到一定程度后由黑荆棘安保公司提供给活跃成员。"] = "Пергамент с формулой зелья для перехода к Последовательности 7, предоставляемый Охранной компанией Чёрный Чертополох активным членам после достижения определенного уровня пищеварения.",
    ["记录着晋升至序列8的魔药配方的羊皮纸，消化进度达到一定程度后由黑荆棘安保公司提供给积攒足够贡献的活跃成员。"] = "Пергамент, записывающий формулу зелья для перехода к Последовательности 8, предоставляемый Охранной компанией Чёрный Чертополох активным членам, накопившим достаточно очков вклада после достижения определенного уровня прогресса пищеварения.",
    ["许愿神灯"] = "Волшебная лампа желаний",
    ["证明胜者曾登临众神之巅的至高凭证，凭此凭证可于大世界中显现个人雕像，享受众人瞻仰。"] = "Высший сертификат, подтверждающий, что победитель достиг Пика Богов. С этим удостоверением вы можете создать личную статую в открытом мире, чтобы все могли ею восхищаться.",
    ["诞生于铁与血之间，淬炼于烽火之中——通向王座的道路，由征服者的足迹铺就。"] = "Рождённый между железом и кровью, закалённый в огне войны: путь к трону вымощен следами Завоевателя.",
    ["诡秘与变化的结晶，仍在试图变形。"] = "Кристалл тайны и перемен, все еще пытающийся трансформироваться.",
    ["谎言"] = "Ложь",
    ["象征束缚与连接的草本材料。"] = "Травяной материал, символизирующий Связывание и связь.",
    ["贝克兰德东北特产"] = "Северо-восточная специализация Бэкланд",
    ["账单并未消失，只是被转交给了一个更适合付钱的人。"] = "Законопроект не исчез; его просто передали кому-то, более подходящему для оплаты.",
    ["质地上乘的纯银饰品。风格古朴，彰显出佩戴者低调又不失考究的品味。"] = "Украшение из чистого серебра превосходной пробы. Выполненное в старинном стиле, оно подчёркивает сдержанный, но изысканный вкус владельца.",
    ["贪婪被消化在肚子里，变成结晶。"] = "Жадность переваривается в чреве, превращаясь в кристаллы.",
    ["贸易战争中使用的货币，可用来买卖货物"] = "Валюта торговых войн, используется для покупки и продажи товаров.",
    ["贸易货物之一，于贸易战争玩法中进行收购和售卖"] = "A type of trade good, used for purchasing and selling in the Trade War gameplay",
    ["赠送给好友，增加100点好友度。"] = "Подарок другу для повышения дружбы на 100 очков.",
    ["赠送给好友，增加10点好友度。"] = "Подарок другу для повышения дружбы на 10 очков.",
    ["赠送给好友，增加20点好友度。"] = "Подарок другу для повышения дружбы на 20 очков.",
    ["赠送给好友，增加500点好友度。"] = "Подарок другу для повышения дружбы на 500 очков.",
    ["超凡山羊角形成的结晶，蕴含稳定的力量属性。"] = "Кристаллы, образовавшиеся из необычных козьих рогов, обладают стабильными свойствами силы.",
    ["超过二十二年历史之物，记录了漫长时间的个人历史，蕴含情感、记忆与命运的痕迹。"] = "Объект с историей более двадцати двух лет, записывающий личную историю на протяжении длительного времени, содержащий следы эмоций, памяти и судьбы.",
    ["足够深刻的记忆，有时会以意想不到的方式留存下来。在特定时刻拯救你，或是将你推入深渊。"] = "Достаточно глубокие воспоминания иногда сохраняются самым неожиданным образом. Они могут спасти вас в определенный момент или столкнуть в пропасть.",
    ["踏遍未知的旅人啊，收下远方赠予的荣光吧！"] = "Путешественник, перешедший неизведанное, прими славу, подаренную далью!",
    ["这一次，转动钥匙，不是为了开启，而是为了锁住什么。"] = "На этот раз ключ поворачивают не для того, чтобы открыть, а чтобы запереть нечто.",
    ["这只手套会把敌人的灵魂剥离到自己身边，吞噬后可获得其生前的能力或专攻强化。但它永不餍足——每一个被放牧的灵魂，都在压低你的生命上限。"] = "Эта перчатка лишит душу врага на вашей стороне; поглотив его, вы можете получить их способности или улучшения специализации, существовавшие до их смерти. Но оно никогда не бывает удовлетворено — каждая душа-марионетка снижает свой предел здоровья.",
    ["这是一个临时道具。"] = "Это временный предмет.",
    ["这是非凡，亦是神性的痕迹，万物皆有神性，万物皆从最初之中诞生，祂的烙印亦在万物之间。"] = "Это необыкновенное, а также след божественности. Все имеет божественность, все рождается от начала, и Его клеймо также находится среди всех вещей.",
    ["这根羽毛，曾划过灵界的边界。"] = "Это перо однажды коснулось границы Мира Духов.",
    ["透过它，灵体清晰，现实模糊。战斗中开启灵视时，能获得灵体的祝福，持续恢复生命并降低受到的伤害，但灵视更短、冷却更长。结束后视力受损，格挡与防御降低。"] = "Благодаря ему духовное тело становится ясным, а реальность размывается. Открытие духовного видения в бою может дать благословение духовного тела, непрерывно восстанавливая здоровье и уменьшая получаемый урон, но духовное зрение короче и имеет более длительное время восстановления. После его окончания зрение ухудшается, блокировка и защита снижаются.",
    ["通过召唤-星灵奇装获得，用于在星灵秘库商店中兑换奖励。"] = "Получается через костюм Призыва Звездного Духа и используется для обмена на награды в секретном магазине Звездного Духа.",
    ["通过召唤-灵界焕容获得，用于在灵幻祭坛商店中兑换奖励。"] = "Получается посредством преобразования мира призыва-духов и используется для обмена на награды в магазине алтаря духовных иллюзий.",
    ["通过召唤-灵界焕容获得，用于在美神馈赠商店中兑换奖励。"] = "Получается через «Призыв — Преображение духовного мира», используется для обмена на награды в магазине «Дары Богини Красоты».",
    ["通过完成每日躺赢任务获取，可用于兑换魔药材料"] = "Можно получить за выполнение ежедневных заданий легкой победы. Используется для обмена на материалы зелий.",
    ["通过灵界焕容获得，用于在美神馈赠商店中兑换奖励。"] = "Получается посредством Трансформации Мира Духов и используется для обмена на награды в Магазине подарков Богини.",
    ["速度被凝固在咸涩的液体里。"] = "Спид затвердевает в соленой жидкости.",
    ["速度被凝固在透明的液体里。"] = "Спид затвердевает в прозрачной жидкости.",
    ["邀请人脉进行互动，增加好感度，提升羁绊等级"] = "Приглашайте контакты к взаимодействию, повышайте благосклонность и уровень связей.",
    ["邓恩·史密斯的历史投影，重现了原主的形态与部分能力。"] = "Историческая проекция Данна Смита, воссоздающая форму и частичные способности оригинала.",
    ["醇厚蜂蜜辅以烟熏猪肉，早餐的绝佳伴侣。培根加蛋，我的伙伴。"] = "Мягкий мед в сочетании с копченой свининой — идеальный компаньон для завтрака. Бекон и яйца, мой партнер.",
    ["醇香的酒液，静静地流淌。"] = "Мягкий, ароматный ликер, льющийся тихо.",
    ["采自六臂灰猩身上，强化力量与野性仪式的辅材。"] = "Добыто с шестирукой серой гориллы; вспомогательный материал для ритуалов укрепления силы и первобытной дикости.",
    ["采自天然晶簇，用于精神与灵性稳定的常见宝石。"] = "Собран из кластеров природных кристаллов — распространенного драгоценного камня, используемого для умственной и духовной стабильности.",
    ["采自黑色矿脉，用于封印与防护的黑色矿石。"] = "Собранная из черных минеральных жил, черная руда используется для запечатывания и защиты.",
    ["重压之下依然保持完整。"] = "Сохраняет целостность даже под сильнейшим давлением.",
    ["野性与理智在血液中交战。"] = "Дикость и разум борются в крови.",
    ["金属小药瓶，里面装半瓶深蓝药水。"] = "Маленький металлический пузырек, содержащий полбутылки темно-синего зелья.",
    ["金币用于提升等级、购买棋子。"] = "Золотые монеты, используемые для повышения уровня и покупки шахматных фигур.",
    ["金秋湖加工品"] = "Переработанный продукт озера Золотой Осени",
    ["金秋湖特产工艺品"] = "Особые поделки на озере «Золотая осень»",
    ["金秋湖特产鱼类"] = "Фирменная рыба озера Золотой Осени",
    ["金红色的酒液像混杂了血液的稀薄蜂蜜，甜润甘醇，谨防贪杯。"] = "Золотисто-красный напиток подобен жидкому меду, смешанному с кровью; сладкий и мягкий, но остерегайтесь чрезмерного баловства.",
    ["金色的庇护，藏在细微的粉末里。"] = "Золотое убежище, спрятанное в мелком порошке.",
    ["金色的粉末，是凝固的清醒。"] = "Золотой порошок – это затвердевшая прозрачность.",
    ["铁路大亨-升级火车消耗的货币"] = "Rail Tycoon — валюта, расходуемая на модернизацию поезда.",
    ["铁路大亨-玩法内货币"] = "Rail Tycoon — внутриигровая валюта",
    ["铁路大亨-进入玩法消耗的门票"] = "Железнодорожный магнат — для входа в режим требуется билет.",
    ["铁路大亨玩法中，商会认可的一种等价物，以票券的形式发放。"] = "Эквивалент, признанный Торгово-промышленной палатой в игровом процессе Railway Tycoon, выдаваемый в виде ваучеров.",
    ["银光流转的茶具雕琢着华丽的纹章，下午茶时光因它而更显优雅。     "] = "Светящийся серебром чайный сервиз украшен великолепными эмблемами, которые делают послеобеденное чаепитие еще более элегантным.",
    ["银白色、雕刻有花纹的子弹"] = "Серебристо-белая пуля с выгравированными узорами.",
    ["银色的血液，冰冷又温热。"] = "Серебряная кровь, холодная, но теплая.",
    ["铸造神话品质胸针<Highlight>（冒险倾向）</>的关键材料。\n\n铸造需消耗<Highlight>15</>个灰雾尘埃，得到64装等<Highlight>冒险倾向</>神话品质胸针。\n随赛季进程，将开放冒险倾向神话胸针的装等提升，提升时消耗一定数量的<Highlight>灰雾尘埃</>。\n\n每周可通过队伍副本、团队副本、世界冒险秘宝<Highlight>直接获取</>至多<Highlight>3</>个灰雾尘埃。未获取个数可累计至下周，至多累计至<Highlight>15</>个。"] = "Ключевой материал для создания броши мифического качества <Highlight>(для приключений)</>.\n\nДля создания требуется <Highlight>15</> шт. пыли серого тумана, в результате вы получите брошь мифического качества 64 ур. снаряжения <Highlight>(для приключений)</>.\nПо ходу сезона откроется возможность повышать уровень снаряжения мифической броши для приключений, для чего потребуется определенное количество <Highlight>пыли серого тумана</>.\n\nКаждую неделю в групповых подземельях, рейдах и сокровищницах приключений в мире можно <Highlight>напрямую получить</> до <Highlight>3</> шт. пыли серого тумана. Неполученное количество переносится на следующую неделю, максимум до <Highlight>15</> шт.",
    ["铸造神话品质胸针<Highlight>（竞技倾向）</>的关键材料。\n\n铸造需消耗<Highlight>15</>个灰雾晶砾，得到64装等<Highlight>竞技倾向</>神话品质胸针。\n随赛季进程，将开放竞技倾向神话胸针的装等提升，提升时消耗一定数量的<Highlight>灰雾晶砾</>。\n\n每周可通过终末猎杀、四方联赛、猎城战/高原战、以战养战秘宝<Highlight>直接获取</>至多<Highlight>3</>个灰雾晶砾。未获取个数可累计至下周，至多累计至<Highlight>15</>个。"] = "Ключевой материал для создания броши мифического качества <Highlight>(соревновательная)</>.\n\nДля создания требуется <Highlight>15</> кристаллических осколков серого тумана, позволяющих получить брошь мифического качества <Highlight>соревновательной направленности</> 64-го ур. снаряжения.\nПо ходу сезона откроется возможность повышать ур. снаряжения мифической броши, расходуя определенное количество <Highlight>кристаллических осколков серого тумана</>.\n\nЕженедельно можно <Highlight>напрямую получить</> до <Highlight>3</> осколков в «Финальной охоте», «Четырехсторонней лиге», «Охоте за городом / Битве на плато» и за сокровища военного развития. Неполученные попытки переносятся на следующую неделю, вплоть до <Highlight>15</> осколков.",
    ["锋利依旧，杀意未散。"] = "Всё так же остра, и жажда убийства не угасла.",
    ["镶嵌红宝石的金戒指闪动光辉。濒死时从近处敌人身上汲取血肉，一次次从死亡边缘复生。但丢失理智的代价是，战斗中你偶尔会变得迟钝、移速降低。"] = "Золотое кольцо, инкрустированное рубинами, сверкает блеском. Находясь на грани смерти, он вытягивает плоть и кровь из ближайших врагов, снова и снова возрождаясь на краю смерти. Но цена потери здравомыслия заключается в том, что вы иногда становитесь медленными и снижаете скорость передвижения во время боя.",
    ["长出完整人脸结构的异常玫瑰，常用于精神或诡秘仪式。"] = "Необычная роза, у которой выросла полная структура человеческого лица, часто используемая в мысленных или таинственных ритуалах.",
    ["长期与灵界相通的古井水，带有未知风险。"] = "Вода из древнего колодца, долгое время сообщавшегося с Миром Духов, таит неведомую опасность.",
    ["长期暴露在强光环境下形成的矿石，内部蕴含微弱但稳定的光辉灵性。"] = "Руда, образовавшаяся в результате длительного воздействия яркого света, содержит внутри слабую, но стабильную сияющую духовность.",
    ["门后是什么？连钥匙自己都不知道。"] = "Что находится за Дверью? Даже самого ключа не знает.",
    ["闪耀淡金色微光的金币，是俱乐部对每位成员奉献的认可与奖赏，可在俱乐部商店兑换各类商品。"] = "Золотая монета с бледно-золотым отливом — признание и награда за вклад каждого члена в Клуб; можно обменять на различные товары в Клубном магазине.",
    ["闻到战斗的气息，将军会化作恶灵定期现身，追踪仇敌的方向进行追踪攻击，造成伤害、眩晕并刻下仇敌印记。但要记得离它远一点，主人也是它的仇敌。"] = "Почуяв запах битвы, Генерал превратится в Злого духа. и появляются периодически, отслеживая направление врага для выполнения отслеживающих атак, нанесения урона, оглушения и вырезания вражеской метки. Но не забывайте держаться от этого подальше; хозяин также является его Врагом.",
    ["队长，你看，我们又一次拯救了廷根。"] = "Капитан, смотрите, мы снова спасли Тингена.",
    ["阳光被囚禁在了石头里，仍试图挣脱。"] = "Солнечный свет заточен в камне и все еще пытается вырваться на свободу.",
    ["阴影斗篷"] = "Теневой плащ",
    ["阿兹克·艾格斯的历史投影，重现了原主的形态与部分能力。"] = "A historical projection of Azik Eggers, recreating the form and partial abilities of the original owner.",
    ["阿尔杰·威尔逊的历史投影，重现了原主的形态与部分能力。"] = "Историческая проекция Алджера Уилсона, воссоздающая форму и частичные способности оригинала.",
    ["隐秘材料制成的染料，散发着莹润的光泽。"] = "Краситель, изготовленный из секретных материалов, излучающий блестящее свечение.",
    ["集齐15个可以获得秘偶先祖铠甲，也可用于秘偶先祖铠甲的培养。"] = "Collect 15 to obtain the marionette Ancestor Armor, which can also be used for the cultivation of the marionette Ancestor Armor.",
